/// The behavior word for a state id. Ids outside `0..BLOCK_STATE_COUNT` fall
/// back to state 0 (air), mirroring `Block.stateById`.
pub fn behavior_of(id: StateId) -> u32 {
    let id = id.0 as u32;
    let idx = BLOCK_BEHAVIOR_RUNS.partition_point(|(start, _, _)| *start as u32 <= id);
    if idx == 0 {
        return BLOCK_BEHAVIOR_RUNS[0].2;
    }
    let (start, len, word) = BLOCK_BEHAVIOR_RUNS[idx - 1];
    if id < start as u32 + len as u32 {
        word
    } else {
        BLOCK_BEHAVIOR_RUNS[0].2
    }
}
